                "....kkBBBBkk....",
                "......kBBk......",
                ".....kBbbBk.....",
                ".....kbkkbk.....",
                "......k..k......",
                "................",
            ],
        ]),
        // eagleB
        Figure(colours: ["k": (0.10, 0.07, 0.06), "B": (0.38, 0.25, 0.16), "b": (0.25, 0.16, 0.10), "W": (0.95, 0.95, 0.92)], frames: [
            [
                "................",
                ".......kk.......",
                "......kWWk......",
                "......kWWk......",
                ".....kBBBBk.....",
                "...kkBBBBBBkk...",
                "..kBBBBbbBBBBk..",
                ".kBBbBBbbBBbBBk.",
                ".kBbkBBBBBBkbBk.",
                ".kbk.kBBBBk.kbk.",
                "..k..kBBBBk..k..",
                "......kBBk......",
                ".....kBbbBk.....",
                ".....kbkkbk.....",
                "......k..k......",
                "................",
            ],
        ]),
    ]

    /// The land and the landmarks in one sheet: the 16 × 16 tiles in a row
    /// along the top, then the 32 × 32 landmarks. Where a landmark
    /// has nothing, the sheet is pure magenta, which the shader reads as
    /// "show the land beneath".
    static let sheetSize = (width: terrain.count * 16 + landmarks.count * 32, height: 32)

    static func sheet() -> CGImage? {
        let width = sheetSize.width, height = sheetSize.height
        // sRGB, named, so the numbers reach the shader as written here.
        guard let space = CGColorSpace(name: CGColorSpace.sRGB),
              let context = CGContext(data: nil, width: width, height: height, bitsPerComponent: 8, bytesPerRow: 0,
                                      space: space,
                                      bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return nil }
        context.setShouldAntialias(false)
        context.setFillColor(CGColor(srgbRed: 1, green: 0, blue: 1, alpha: 1))
        context.fill(CGRect(x: 0, y: 0, width: width, height: height))
        // The context's origin is at the bottom-left; pictures are listed from the top.
        context.translateBy(x: 0, y: CGFloat(height))
        context.scaleBy(x: 1, y: -1)
        for (i, tile) in terrain.enumerated() {
            paint(tile, colours: palette, in: context, at: CGPoint(x: CGFloat(i * 16), y: 0), pixel: 1)
        }
        for (i, mark) in landmarks.enumerated() {
            paint(mark, colours: palette, in: context, at: CGPoint(x: CGFloat(terrain.count * 16 + i * 32), y: 0), pixel: 1)
        }
        return context.makeImage()
    }

    /// Paints one picture, each of its pixels a square `pixel` wide, in a
    /// context whose origin is at the top-left.
    static func paint(_ rows: [String], colours: [Character: Colour], in context: CGContext, at origin: CGPoint, pixel: CGFloat) {
        for (y, row) in rows.enumerated() {
            for (x, letter) in row.enumerated() {
                guard let colour = colours[letter] else { continue }
                context.setFillColor(CGColor(srgbRed: colour.0, green: colour.1, blue: colour.2, alpha: 1))
                context.fill(CGRect(x: origin.x + CGFloat(x) * pixel, y: origin.y + CGFloat(y) * pixel, width: pixel, height: pixel))
            }
        }
    }
}
